'use client';

import { useState } from 'react';
import Link from 'next/link';
import useSWRInfinite from 'swr/infinite';
import { Plus, Edit2, Trash2, Search, Eye, RefreshCw, AlertCircle, CheckCircle2, XCircle } from 'lucide-react';

const fetcher = (url: string) => fetch(url).then(res => res.json());

export default function AdminPropertiesManager() {
  const [searchTerm, setSearchTerm] = useState('');

  // G57 & G58: Pagina├º├úo cursor-based + SWR
  const getKey = (pageIndex: number, previousPageData: any) => {
    if (previousPageData && !previousPageData.nextCursor) return null; // reached the end

    let url = `/api/properties/admin?search=${encodeURIComponent(searchTerm)}`;
    if (pageIndex !== 0 && previousPageData.nextCursor) {
      url += `&cursor=${previousPageData.nextCursor}`;
    }
    return url;
  };

  const { data, size, setSize, isValidating, mutate } = useSWRInfinite(getKey, fetcher, {
    revalidateOnFocus: false, // Evita re-fetch desnecess├írio
  });

  const properties = data ? data.flatMap(page => page.properties) : [];
  const isLoadingInitialData = !data && isValidating;
  const isLoadingMore = isValidating && size > 0 && data && typeof data[size - 1] === "undefined";
  const isEmpty = data?.[0]?.properties.length === 0;
  const isReachingEnd = isEmpty || (data && data[data.length - 1]?.nextCursor === null);

  const handleDelete = async (id: string) => {
    if (confirm('­ƒÜ¿ ATEN├ç├âO: Tem certeza que deseja excluir permanentemente este im├│vel?')) {
      const res = await fetch(`/api/properties/${id}`, { method: 'DELETE' });
      if (res.ok) {
        mutate(); // Revalida o cache local do SWR
      } else {
        alert('Erro ao excluir im├│vel.');
      }
    }
  };

  const handleToggleStatus = async (id: string, currentStatus: boolean) => {
    const newStatus = !currentStatus;
    const action = newStatus ? 'Reativar an├║ncio?' : 'Marcar como ALUGADO (ocultar das buscas)?';
    if (confirm(action)) {
      const res = await fetch(`/api/properties/${id}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ isActive: newStatus })
      });
      if (res.ok) {
        mutate();
      } else {
        alert('Erro ao alterar status.');
      }
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight text-gray-900 dark:text-white">Gerenciar Im├│veis</h1>
          <p className="text-gray-500 dark:text-gray-400 mt-1">Cat├ílogo de an├║ncios no sistema.</p>
        </div>
        <Link 
          href="/dashboard/admin/imoveis/novo"
          className="bg-indigo-600 hover:bg-indigo-700 text-white px-5 py-2.5 rounded-xl font-bold flex items-center justify-center gap-2 transition-all shadow-lg shadow-indigo-500/30"
        >
          <Plus size={20} />
          Novo Im├│vel
        </Link>
      </div>

      <div className="bg-white dark:bg-[#111] rounded-2xl border border-gray-200 dark:border-white/10 overflow-hidden shadow-sm">
        <div className="p-4 border-b border-gray-200 dark:border-white/10 flex flex-col sm:flex-row justify-between gap-4">
          <div className="relative w-full max-w-md">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={18} />
            <input 
              type="text" 
              placeholder="Buscar por t├¡tulo ou endere├ºo..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-gray-50 dark:bg-white/5 border border-gray-200 dark:border-white/10 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
            />
          </div>
          <button 
            onClick={() => mutate()}
            className="flex items-center gap-2 px-3 py-2 text-sm text-gray-500 hover:text-gray-900 dark:hover:text-white transition-colors"
          >
            <RefreshCw size={16} className={isValidating ? 'animate-spin' : ''} />
            Atualizar
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm whitespace-nowrap">
            <thead className="bg-gray-50 dark:bg-white/5 text-gray-500 dark:text-gray-400 border-b border-gray-100 dark:border-white/10">
              <tr>
                <th className="px-6 py-4 font-bold">Im├│vel</th>
                <th className="px-6 py-4 font-bold">Valor (Aluguel)</th>
                <th className="px-6 py-4 font-bold">M├®tricas</th>
                <th className="px-6 py-4 font-bold text-right">A├º├Áes</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 dark:divide-white/5">
              {isLoadingInitialData ? (
                <tr>
                  <td colSpan={4} className="px-6 py-12 text-center text-gray-400">
                    <RefreshCw size={24} className="animate-spin mx-auto mb-2 text-indigo-500" />
                    Carregando im├│veis...
                  </td>
                </tr>
              ) : isEmpty ? (
                <tr>
                  <td colSpan={4} className="px-6 py-12 text-center text-gray-500">
                    <AlertCircle size={24} className="mx-auto mb-2 opacity-50" />
                    Nenhum im├│vel encontrado.
                  </td>
                </tr>
              ) : properties.map((prop: any) => (
                <tr key={prop.id} className="hover:bg-gray-50 dark:hover:bg-white/5 transition-colors group">
                  <td className="px-6 py-4">
                    <div className="flex items-center gap-4">
                      {prop.featuredImage ? (
                        <img src={prop.featuredImage} alt="" className="w-14 h-14 rounded-xl object-cover shadow-sm border border-black/5" />
                      ) : (
                        <div className="w-14 h-14 rounded-xl bg-gray-100 dark:bg-white/5 border border-black/5 flex items-center justify-center">
                          <span className="text-[10px] text-gray-400">Sem Imagem</span>
                        </div>
                      )}
                      <div>
                        <Link href={`/imovel/${prop.id}`} target="_blank" className="font-bold text-gray-900 dark:text-white hover:text-indigo-600 dark:hover:text-indigo-400 transition-colors">
                          {prop.title}
                        </Link>
                        <p className="text-xs text-gray-500 truncate max-w-[200px] mt-0.5">{prop.address}</p>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <span className="font-black text-indigo-600 dark:text-indigo-400 text-base">
                      R$ {prop.basePrice.toLocaleString('pt-BR')}
                    </span>
                  </td>
                  <td className="px-6 py-4">
                    <div className="flex flex-col gap-1">
                      <div className="flex items-center gap-1.5 text-xs text-gray-500 font-medium">
                        <Eye size={14} className="text-emerald-500" /> {prop.viewCount} views
                      </div>
                      <div className="mt-1">
                        {prop.isActive === false ? (
                          <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400">
                            <CheckCircle2 size={10} /> Alugado (Inativo)
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-[10px] font-bold px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400">
                            Ativo
                          </span>
                        )}
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 text-right">
                    <div className="flex items-center justify-end gap-2">
                      <button 
                        onClick={() => handleToggleStatus(prop.id, prop.isActive !== false)}
                        className={`p-2 rounded-lg transition-colors ${
                          prop.isActive === false 
                            ? 'text-amber-500 hover:bg-amber-50 dark:hover:bg-amber-900/20' 
                            : 'text-gray-400 hover:text-amber-600 hover:bg-amber-50 dark:hover:bg-amber-900/20'
                        }`}
                        title={prop.isActive === false ? "Reativar An├║ncio" : "Marcar como Alugado"}
                      >
                        {prop.isActive === false ? <XCircle size={18} /> : <CheckCircle2 size={18} />}
                      </button>
                      <Link 
                        href={`/dashboard/admin/imoveis/${prop.id}/editar`}
                        className="p-2 text-gray-400 hover:text-indigo-600 hover:bg-indigo-50 dark:hover:bg-indigo-900/20 rounded-lg transition-colors"
                        title="Editar Im├│vel"
                      >
                        <Edit2 size={18} />
                      </Link>
                      <button 
                        onClick={() => handleDelete(prop.id)}
                        className="p-2 text-gray-400 hover:text-red-600 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-lg transition-colors"
                        title="Excluir Permanentemente"
                      >
                        <Trash2 size={18} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Load More Button */}
        {!isEmpty && !isReachingEnd && (
          <div className="p-4 border-t border-gray-100 dark:border-white/10 text-center">
            <button
              onClick={() => setSize(size + 1)}
              disabled={isLoadingMore}
              className="px-6 py-2 bg-gray-100 dark:bg-white/5 hover:bg-gray-200 dark:hover:bg-white/10 text-gray-600 dark:text-gray-300 font-semibold rounded-full text-sm transition-colors disabled:opacity-50"
            >
              {isLoadingMore ? 'Carregando...' : 'Carregar mais'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { toast } from 'sonner';
import { ArrowLeft, Building, MapPin, DollarSign, Home, Maximize, Loader2, ImagePlus, X, Zap } from 'lucide-react';
import Link from 'next/link';
import { supabase } from '@/utils/supabase';
import imageCompression from 'browser-image-compression';

export default function EditPropertyForm({ property }: { property: any }) {
  const router = useRouter();
  const [isLoading, setIsLoading] = useState(false);

  type ImageItem = {
    id: string; // local or db id
    url: string; // preview url or db url
    file?: File;
    compressedFile?: File;
    compressInfo?: { original: number; compressed: number };
    isExisting?: boolean;
  };

  const initialImages: ImageItem[] = (property.images && property.images.length > 0) 
    ? property.images.map((img: any) => ({ id: img.id, url: img.url, isExisting: true }))
    : (property.featuredImage ? [{ id: 'featured', url: property.featuredImage, isExisting: true }] : []);

  const [images, setImages] = useState<ImageItem[]>(initialImages);

  const handleImageSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const selectedFiles = Array.from(e.target.files);

      const newItems: ImageItem[] = [];

      for (const selectedFile of selectedFiles) {
        const id = Math.random().toString(36).substring(7);
        const url = URL.createObjectURL(selectedFile);

        let compressedFile = selectedFile;
        let compressInfo = null;

      // G59: Comprimir e converter para WebP antes do upload
        try {
          const options = {
            maxSizeMB: 0.5,
            maxWidthOrHeight: 1280,
            useWebWorker: true,
            fileType: 'image/webp',
          };
          compressedFile = await imageCompression(selectedFile, options);
          compressInfo = {
            original: Math.round(selectedFile.size / 1024),
            compressed: Math.round(compressedFile.size / 1024),
          };
        } catch (error) {
          console.error("Compression failed", error);
        }

        newItems.push({
          id,
          url,
          file: selectedFile,
          compressedFile,
          compressInfo: compressInfo ?? undefined,
          isExisting: false
        });
      }

      setImages(prev => [...prev, ...newItems]);
    }
  };

  const removeImage = (idToRemove: string) => {
    setImages(prev => prev.filter(img => img.id !== idToRemove));
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setIsLoading(true);

    const formData = new FormData(e.currentTarget);
    const data = Object.fromEntries(formData.entries());

    // Map checkboxes to booleans
    data.petFriendly = (formData.get('petFriendly') === 'on') as any;
    data.furnished = (formData.get('furnished') === 'on') as any;

    try {
      const uploadedFilePaths: string[] = [];
      const finalImageUrls: string[] = [];

      toast.info('ÔÜí Processando imagens...');

      for (const img of images) {
        if (img.isExisting) {
          finalImageUrls.push(img.url);
        } else if (img.compressedFile || img.file) {
          const uploadFile = img.compressedFile ?? img.file!;
          const fileName = `${Math.random().toString(36).substring(2, 15)}_${Date.now()}.webp`;
          const filePath = `imoveis/${fileName}`;
          uploadedFilePaths.push(filePath);

          const { error: uploadError } = await supabase.storage
            .from('property-images')
            .upload(filePath, uploadFile, { cacheControl: '3600', upsert: false, contentType: 'image/webp' });

          if (uploadError) throw new Error('Falha no upload da imagem.');

          const { data: urlData } = supabase.storage
            .from('property-images')
            .getPublicUrl(filePath);

          finalImageUrls.push(urlData.publicUrl);
        }
      }

      data.images = finalImageUrls as any;

      const response = await fetch(`/api/admin/properties/${property.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data),
      });

      if (!response.ok) {
        // Rollback: remover imagens ├│rf├ús do bucket
        if (uploadedFilePaths.length > 0) {
          await supabase.storage.from('property-images').remove(uploadedFilePaths);
        }
        throw new Error('Falha ao atualizar im├│vel.');
      }

      toast.success('Ô£à Im├│vel atualizado com sucesso!');
      router.push('/dashboard/admin/imoveis');
      router.refresh();
    } catch (error) {
      toast.error('Erro ao atualizar. Tente novamente.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-[#0a0a0a] pb-24">
      {/* Header */}
      <header className="bg-white/80 dark:bg-black/80 backdrop-blur-md border-b border-gray-200 dark:border-white/10 px-4 h-16 flex items-center sticky top-0 z-40">
        <div className="max-w-4xl mx-auto w-full flex items-center justify-between">
          <Link href="/dashboard/admin/imoveis" className="flex items-center gap-2 text-gray-600 dark:text-gray-300 hover:text-indigo-600 transition-colors">
            <ArrowLeft size={20} />
            <span className="font-medium">Voltar</span>
          </Link>
          <h1 className="font-bold text-gray-900 dark:text-white">Editar Im├│vel</h1>
          <div className="w-20" /> {/* Spacer */}
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 sm:px-6 py-8">
        <form onSubmit={handleSubmit} className="space-y-8">

          <section className="bg-white dark:bg-[#111] p-6 rounded-3xl border border-gray-100 dark:border-white/10 shadow-sm space-y-6">
            <h2 className="text-xl font-bold flex items-center gap-2 border-b border-gray-100 dark:border-white/10 pb-4">
              <Building className="text-indigo-600" /> Informa├º├Áes Principais
            </h2>

            <div className="space-y-4">
              <div>
                <label className="block text-sm font-semibold mb-2">T├¡tulo do An├║ncio</label>
                <input 
                  required name="title" type="text" defaultValue={property.title}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-white/5 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                />
              </div>

              <div>
                <label className="block text-sm font-semibold mb-2">Descri├º├úo Detalhada</label>
                <textarea 
                  required name="description" rows={4} defaultValue={property.description}
                  className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-white/5 focus:ring-2 focus:ring-indigo-600 outline-none transition-all resize-none"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-semibold mb-2 flex items-center gap-1"><DollarSign size={16}/> Valor Mensal (R$)</label>
                  <input 
                    required name="basePrice" type="number" step="0.01" defaultValue={property.basePrice}
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-white/5 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                  />
                </div>
                <div>
                  <label className="block text-sm font-semibold mb-2 flex items-center gap-1"><Maximize size={16}/> ├ürea ├Ütil (m┬▓)</label>
                  <input 
                    required name="areaUseful" type="number" defaultValue={property.areaUseful}
                    className="w-full px-4 py-3 rounded-xl border border-gray-200 dark:border-white/10 bg-gray-50 dark:bg-white/5 focus:ring-2 focus:ring-indigo-600 outline-none transition-all"
                  />
                </div>
              </div>
            </div>
          </section>

          <section className="bg-white dark:bg-[#111] p-6 rounded-3xl border border-gray-100 dark:border-white/10 shadow-sm space-y-6">
            <h2 className="text-xl font-bold flex items-center gap-2 border-b border-gray-100 dark:border-white/10 pb-4">
