export default function Home() {
  const [selectedPropertyId, setSelectedPropertyId] = useState<string | null>(null);
  const [polygonFilteredIds, setPolygonFilteredIds] = useState<string[] | null>(null);
  const { filters, hasActiveFilters, setDrawerOpen, setFilter, mapBounds, setMapBounds } = useFilterStore();

  const fetcher = (url: string) => fetch(url).then(res => {
    if (!res.ok) throw new Error('Falha ao carregar im├│veis.');
    return res.json();
  });

  const getKey = (pageIndex: number, previousPageData: any) => {
    if (previousPageData && !previousPageData.nextCursor) return null;
    const params = new URLSearchParams();
    if (filters.minPrice > 0) params.append('minPrice', filters.minPrice.toString());
    if (filters.maxPrice < 10000000) params.append('maxPrice', filters.maxPrice.toString()); // Usando um valor alto como teto
    if (filters.minBedrooms > 0) params.append('bedrooms', filters.minBedrooms.toString());
    if (filters.petFriendly !== null) params.append('petFriendly', filters.petFriendly.toString());
    if (filters.furnished !== null) params.append('furnished', filters.furnished.toString());
    if (filters.city !== null) params.append('city', filters.city);
    if (filters.propertyCategory) params.append('propertyCategory', filters.propertyCategory);
    if (filters.transactionType) params.append('transactionType', filters.transactionType);
    params.append('limit', '10');
    if (pageIndex > 0 && previousPageData.nextCursor) {
      params.append('cursor', previousPageData.nextCursor);
    }

    // Sincronia Espacial: Passar os limites do mapa tamb├®m para o Feed (Sidebar)
    if (debouncedMapBounds) {
      params.append('n', debouncedMapBounds.n.toString());
      params.append('s', debouncedMapBounds.s.toString());
      params.append('e', debouncedMapBounds.e.toString());
      params.append('w', debouncedMapBounds.w.toString());
    }

    return `/api/properties?${params.toString()}`;
  };

  const { data, error, size, setSize, isValidating } = useSWRInfinite(getKey, fetcher, { revalidateOnFocus: false });

  const debouncedMapBounds = useDebounce(mapBounds, 300);

  // Buscar os dados ultra-leves globais para o Mapa
  const getMapKey = () => {
    const params = new URLSearchParams();
    if (filters.minPrice > 0) params.append('minPrice', filters.minPrice.toString());
    if (filters.maxPrice < 10000000) params.append('maxPrice', filters.maxPrice.toString());
    if (filters.minBedrooms > 0) params.append('bedrooms', filters.minBedrooms.toString());
    if (filters.petFriendly !== null) params.append('petFriendly', filters.petFriendly.toString());
    if (filters.furnished !== null) params.append('furnished', filters.furnished.toString());
    if (filters.city !== null) params.append('city', filters.city);
    if (filters.propertyCategory) params.append('propertyCategory', filters.propertyCategory);
    if (filters.transactionType) params.append('transactionType', filters.transactionType);
    if (debouncedMapBounds) {
      params.append('n', debouncedMapBounds.n.toString());
      params.append('s', debouncedMapBounds.s.toString());
      params.append('e', debouncedMapBounds.e.toString());
      params.append('w', debouncedMapBounds.w.toString());
    }
    return `/api/properties/map?${params.toString()}`;
  };

  const { data: mapPropertiesData } = useSWR(getMapKey, fetcher, { revalidateOnFocus: false });
  const mapProperties = mapPropertiesData || [];

  const properties = data ? data.flatMap(page => page.properties) : [];
  const isLoadingInitialData = !data && !error;
  const isLoadingMore = isLoadingInitialData || (size > 0 && data && typeof data[size - 1] === "undefined");
  const isEmpty = data?.[0]?.properties?.length === 0;
  const isReachingEnd = isEmpty || (data && data[data.length - 1]?.nextCursor === null);

  // Pre├ºo m├®dio para Badge "Abaixo da M├®dia" nos cards
  const avgPrice = useMemo(() => {
    if (properties.length === 0) return 0;
    return properties.reduce((sum, p) => sum + p.price, 0) / properties.length;
  }, [properties]);

  // A barra lateral s├│ renderiza os paginados, mas se houver filtro poligonal, 
  // ela exibe apenas os im├│veis que caem dentro do pol├¡gono.
  const propertiesToDisplay = polygonFilteredIds
    ? properties.filter(p => polygonFilteredIds.includes(p.id))
    : properties;

  // O mapa renderiza TODOS os im├│veis globais que batem com os filtros textuais/num├®ricos,
  // e o Lasso filtra esses im├│veis se houver pol├¡gono.
  const mapPropertiesToDisplay = polygonFilteredIds 
    ? mapProperties.filter((p: any) => polygonFilteredIds.includes(p.id))
    : mapProperties;

  // Toast when polygon filter is applied
  const handlePolygonFilter = (ids: string[] | null) => {
    setPolygonFilteredIds(ids);
    if (ids !== null) {
      toast.info(`├ürea selecionada`, { description: `${ids.length} im├│ve${ids.length === 1 ? 'l' : 'is'} encontrado${ids.length === 1 ? '' : 's'} na ├írea.` });
    } else {
      toast.success('Sele├º├úo removida', { description: 'Exibindo todos os im├│veis no mapa.' });
    }
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-[var(--background)]">
      <SplashScreen />

      {/* A9: Header com Glassmorphism e busca funcional */}
      <Header propertiesCount={properties.filter(p => isNew((p as any).createdAt || new Date())).length} />

      {/* Main Split Layout */}
      <main className="flex-1 flex overflow-hidden relative">
        {/* Left Panel: Feed ÔÇö visible ONLY on md+ */}
        <section className={`
          flex-col w-full md:w-[480px] lg:w-[550px] bg-gray-50/50 dark:bg-[#0a0a0a] border-r border-gray-200 dark:border-white/5 
          hidden md:flex
        `}>  {/* Filters Bar */}
          <div className="p-4 border-b border-gray-200 dark:border-white/5 bg-white/80 dark:bg-black/60 backdrop-blur-md sticky top-0 z-20">
            <div className="flex items-center justify-between">
              <p className="font-medium text-sm text-gray-600 dark:text-gray-300">
                {isLoadingInitialData ? (
                  <span className="inline-block h-4 w-28 shimmer bg-gray-200 dark:bg-white/10 rounded-full" />
                ) : (
                  <>
                    <span className="text-gray-900 dark:text-white font-black">{propertiesToDisplay.length}</span>
                    {' '}im├│veis {polygonFilteredIds ? 'na ├írea' : 'encontrados'}
                  </>
                )}
              </p>
              <button 
                onClick={() => setDrawerOpen(true)}
                className={`flex items-center gap-2 px-4 py-2 text-sm font-semibold border rounded-full transition-all ${
                  hasActiveFilters 
                    ? 'border-indigo-400 text-indigo-600 dark:text-indigo-400 bg-indigo-50 dark:bg-indigo-900/20 shadow-sm shadow-indigo-200 dark:shadow-indigo-900/30' 
                    : 'border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-200 hover:bg-gray-100 dark:hover:bg-white/5'
                }`}>
                <SlidersHorizontal size={15} />
                <span>Filtros{hasActiveFilters ? ' Ô£ª' : ''}</span>
              </button>
            </div>
            {/* Quick Chips */}
            <div className="flex gap-2 mt-3 overflow-x-auto pb-1 no-scrollbar">
              {[
                { label: '­ƒÉ¥ Pet Friendly', filter: () => setFilter('petFriendly', true) },
                { label: '­ƒøï´©Å Mobiliado',   filter: () => setFilter('furnished', true) },
                { label: '­ƒÅÖ´©Å Gurupi',       filter: () => setFilter('city', 'Gurupi') },
                { label: '­ƒÅø´©Å Natividade',   filter: () => setFilter('city', 'Natividade') },
              ].map(chip => (
                <button
                  key={chip.label}
                  onClick={chip.filter}
                  className="whitespace-nowrap px-3 py-1.5 text-xs font-semibold rounded-full bg-white dark:bg-white/5 border border-gray-200 dark:border-white/10 hover:border-indigo-400 dark:hover:border-indigo-500 hover:text-indigo-600 dark:hover:text-indigo-400 text-gray-600 dark:text-gray-300 transition-all"
                >
                  {chip.label}
                </button>
              ))}
            </div>
          </div>

          {/* List */}
          <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-6">
            {isLoadingInitialData ? (
              <PropertyListSkeleton count={3} />
            ) : error ? (
              <div className="flex flex-col items-center justify-center py-16 text-center">
                <div className="text-4xl mb-4">­ƒÿò</div>
                <p className="font-semibold text-gray-700 dark:text-gray-200">{error?.message || String(error)}</p>
                <button 
                  onClick={() => window.location.reload()}
                  className="mt-4 px-5 py-2 bg-primary text-white rounded-full text-sm font-semibold hover:bg-blue-700 transition-colors"
                >
                  Tentar novamente
                </button>
              </div>
            ) : propertiesToDisplay.length === 0 ? (
              <EmptyStateRadar />
            ) : (
              <>
                {propertiesToDisplay.map((property, index) => (
                  <FadeInItem key={property.id} index={index}>
                    <PropertyCard 
                      property={property as any}
                      avgPrice={avgPrice}
                      onClick={() => setSelectedPropertyId(property.id)} 
                    />
                  </FadeInItem>
                ))}

                {/* Bot├úo de Carregar Mais */}
                {!isReachingEnd && (
                  <div className="text-center py-4">
                    <button
                      onClick={() => setSize(size + 1)}
                      disabled={isLoadingMore}
                      className="px-6 py-2.5 rounded-full border border-indigo-200 dark:border-indigo-900/50 bg-white dark:bg-[#1a1a1a] text-indigo-600 dark:text-indigo-400 font-bold hover:bg-indigo-50 dark:hover:bg-indigo-900/20 transition-all disabled:opacity-50"
                    >
                      {isLoadingMore ? 'Carregando...' : 'Carregar Mais'}
                    </button>
                  </div>
                )}

                {isReachingEnd && !isEmpty && (
                  <div className="text-center py-8">
                    <p className="text-sm text-gray-500">
                      Mostrando <span className="font-bold text-gray-700 dark:text-gray-300">{propertiesToDisplay.length}</span> im├│veis.{' '}
                      <a href="#" className="text-indigo-500 hover:underline font-medium">Ampliar busca?</a>
                    </p>
                  </div>
                )}
              </>
            )}
          </div>
        </section>

        {/* Right Panel: Map ÔÇö always visible, taking full width on mobile */}
        <section className={`
          flex-1 h-full relative z-0 block w-full
        `}>
          <MapComponent 
            properties={mapPropertiesToDisplay}
            onPropertySelect={setSelectedPropertyId} 
            onPolygonFilter={handlePolygonFilter}
            onBoundsChange={setMapBounds}
            onMapInteraction={() => {
              if (filters.city !== null) {
                setFilter('city', null);
                toast('Explora├º├úo Espacial', { description: 'Filtro de cidade limpo pois voc├¬ moveu o mapa manualmente.' });
              }
            }}
          />

          {/* Status pill */}
          <div className="absolute bottom-8 left-1/2 -translate-x-1/2 z-[1010] bg-white/95 dark:bg-black/85 backdrop-blur-md px-4 py-2 rounded-full shadow-lg border border-black/5 dark:border-white/10 flex items-center gap-2 pointer-events-none">
            <div className={`w-2 h-2 rounded-full ${isLoadingInitialData ? 'bg-amber-400 animate-pulse' : 'bg-emerald-500 animate-pulse'}`} />
            <span className="text-xs font-semibold dark:text-gray-200 text-gray-700">
              {isLoadingInitialData ? 'Carregando...' : polygonFilteredIds ? `${mapPropertiesToDisplay.length} na ├írea` : `${mapProperties.length} im├│veis no mapa`}
            </span>
          </div>

        </section>


      </main>

      {/* Bot├úo Contextual do Modo Radar */}
      <CreateRadarButton />

      {/* Filter Drawer */}
      <FilterDrawer />

      {/* Slide-over Sidebar for Property Details */}
      <PropertySidebar 
        propertyId={selectedPropertyId} 
        onClose={() => setSelectedPropertyId(null)} 
      />

    </div>
  );
}

'use client';

import { useState, useRef, useEffect, useCallback } from 'react';
import { useChat } from '@ai-sdk/react';
import { MessageSquare, X, Send, Sparkles, Building, Bed, Maximize, Trash2, ChevronRight, Mic, MicOff } from 'lucide-react';
import { useFilterStore } from '@/store/useFilterStore';
import { useSession } from 'next-auth/react';
import { usePathname } from 'next/navigation';

const STORAGE_KEY = 'aluga_ai_chat_history';
const LAST_VISIT_KEY = 'aluga_ai_last_visit';

// E44: Chips de sugest├úo din├ómicos baseados no contexto da ├║ltima resposta
const SUGGESTION_CHIPS = [
  'Ver mais baratos',
  'Mostrar mobiliados',
  'Pet friendly?',
  'S├│ em Gurupi',
  'Com 2+ quartos',
  'Pr├│ximo ao centro',
];

export default function AIChatbot() {
  const [isOpen, setIsOpen] = useState(false);
  const [showProactive, setShowProactive] = useState(false); // E48
  const [isListening, setIsListening] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const recognitionRef = useRef<any>(null);
  const { setFilter, resetFilters, mapBounds, filters } = useFilterStore();
  const pathname = usePathname();

  // Detecta se estamos numa p├ígina de im├│vel
  const isPropertyPage = pathname?.startsWith('/imovel/');
  const propertyId = isPropertyPage ? pathname.split('/')[2] : undefined;

  const { data: session, status } = useSession();

  // E43: Carregar hist├│rico do localStorage (apenas para fallback offline/anon)
  const [input, setInput] = useState('');

  const { messages, sendMessage, error, setMessages, status: chatStatus } = useChat();

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed && parsed.length > 0) {
            setMessages(parsed);
          }
        } catch (e) {
          console.error('Failed to parse chat history', e);
        }
      }
    }
  }, [setMessages]);

  const isLoading = chatStatus === 'streaming' || chatStatus === 'submitted';

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setInput(e.target.value);
  };

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isLoading) return;
    sendMessage({ text: input }, { body: { propertyId, mapBounds, propertyCategory: filters.propertyCategory } });
    setInput('');
  };

  // Inicializa o Reconhecimento de Voz (E98)
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        recognitionRef.current = new SpeechRecognition();
        recognitionRef.current.continuous = false;
        recognitionRef.current.interimResults = true;
        recognitionRef.current.lang = 'pt-BR';

        recognitionRef.current.onresult = (event: any) => {
          let interimTranscript = '';
          let finalTranscript = '';

          for (let i = event.resultIndex; i < event.results.length; ++i) {
            if (event.results[i].isFinal) {
              finalTranscript += event.results[i][0].transcript;
            } else {
              interimTranscript += event.results[i][0].transcript;
            }
          }

          if (finalTranscript) {
            setInput((prev) => (prev ? prev + ' ' : '') + finalTranscript);
            setIsListening(false);
          } else if (interimTranscript) {
            setInput(interimTranscript);
          }
        };

        recognitionRef.current.onerror = (event: any) => {
          console.error('Speech recognition error', event.error);
          setIsListening(false);
        };

        recognitionRef.current.onend = () => {
          setIsListening(false);
        };
      }
    }
  }, [setInput]);

  const toggleListen = useCallback(() => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if (recognitionRef.current) {
        setInput(''); // Limpa o input antes de ouvir
        recognitionRef.current.start();
        setIsListening(true);
      } else {
        alert('Seu navegador n├úo suporta reconhecimento de voz.');
      }
    }
  }, [isListening, setInput]);

  // E44: Buscar hist├│rico do servidor se estiver logado
  useEffect(() => {
    if (status === 'authenticated') {
      fetch('/api/chat/history')
        .then(res => {
          if (!res.ok) throw new Error('Falha ao carregar hist├│rico');
          return res.json();
        })
        .then(data => {
          if (data?.messages && data.messages.length > 0) {
            setMessages(data.messages);
          }
        })
        .catch(err => {
          console.error("Erro no fetch de hist├│rico:", err);
        });
    }
  }, [status, setMessages]);

  // E48: Verificar se usu├írio voltou ap├│s 2+ dias
  useEffect(() => {
    if (typeof window === 'undefined') return;
    const lastVisit = localStorage.getItem(LAST_VISIT_KEY);
    const now = Date.now();

    if (lastVisit) {
      const diffDays = (now - parseInt(lastVisit)) / (1000 * 60 * 60 * 24);
      if (diffDays >= 2 && messages.length === 0) {
        setShowProactive(true);
      }
    }
    localStorage.setItem(LAST_VISIT_KEY, now.toString());

    // Event listener para abrir programaticamente (Ex: Fallback de im├│veis inativos)
    const handleOpenChatbot = (e: Event) => {
      setIsOpen(true);
      const customEvent = e as CustomEvent;
      if (customEvent.detail?.message) {
        // Envia a mensagem automaticamente ap├│s um pequeno delay para a UI abrir
        setTimeout(() => {
          sendMessage({ text: customEvent.detail.message }, { body: { propertyId, mapBounds, propertyCategory: filters.propertyCategory } });
        }, 500);
      }
    };
    window.addEventListener('open-chatbot', handleOpenChatbot);

    return () => {
      window.removeEventListener('open-chatbot', handleOpenChatbot);
    };
  }, []);

  // E43: Salvar hist├│rico sempre que mensagens mudam (se an├┤nimo)
  useEffect(() => {
    if (typeof window !== 'undefined' && messages.length > 0 && status !== 'authenticated') {
      // Salvar s├│ as ├║ltimas 20 mensagens para n├úo estourar o localStorage
      const toSave = messages.slice(-20);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(toSave));
    }

    // Scroll autom├ítico
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });

    // E95: Sincroniza├º├úo do estado da IA com o Mapa (Zustand)
    if (messages.length > 0) {
      const lastMessage = messages[messages.length - 1];
      if (lastMessage.role === 'assistant' && lastMessage.parts) {
        const searchCall: any = lastMessage.parts.find(p => 
          (p.type === 'tool-searchProperties' || (p as any).toolName === 'searchProperties')
        );
        if (searchCall && (searchCall.state === 'call' || searchCall.state === 'result' || searchCall.state === 'input-available' || searchCall.state === 'output-available')) {
          const args = searchCall.input || searchCall.args || {};
          resetFilters();
          if (args.city)        setFilter('city', args.city);
          if (args.minBedrooms) setFilter('minBedrooms', args.minBedrooms);
          if (args.maxPrice)    setFilter('maxPrice', args.maxPrice);
          if (args.petFriendly !== undefined) setFilter('petFriendly', args.petFriendly);
          if (args.furnished !== undefined)   setFilter('furnished', args.furnished);
        }
      }
    }
  }, [messages, setFilter, resetFilters]);

  // E43: Limpar hist├│rico
  const clearHistory = () => {
    setMessages([]);
    if (typeof window !== 'undefined') {
      localStorage.removeItem(STORAGE_KEY);
    }
  };

  // E44: Enviar sugest├úo ao clicar no chip
  const handleChipClick = (chip: string) => {
    sendMessage({ text: chip }, { body: { propertyId, mapBounds, propertyCategory: filters.propertyCategory } });
  };

  const renderToolInvocation = (toolInvocation: any) => {
    const toolName = toolInvocation.toolName || (toolInvocation.type?.startsWith('tool-') ? toolInvocation.type.replace('tool-', '') : '');

    if (toolName === 'searchProperties') {
      if (toolInvocation.state === 'call' || toolInvocation.state === 'input-streaming' || toolInvocation.state === 'input-available') {
        return (
          <div key={toolInvocation.toolCallId} className="bg-indigo-50 dark:bg-indigo-900/20 text-indigo-600 dark:text-indigo-400 p-3 rounded-xl text-sm flex items-center gap-2 animate-pulse mt-2">
            <Sparkles size={15} /> Buscando im├│veis perfeitos...
          </div>
        );
      }
      if (toolInvocation.state === 'result' || toolInvocation.state === 'output-available') {
        const payload = toolInvocation.output || toolInvocation.result;
        if (!payload) return null;

        const { resultsCount, properties } = payload;
        if (resultsCount === 0) {
          return (
            <div key={toolInvocation.toolCallId} className="bg-gray-100 dark:bg-white/5 p-3 rounded-xl text-sm text-gray-500 dark:text-gray-400 mt-2">
              ­ƒÿö Nenhum im├│vel encontrado com esses filtros.
            </div>
          );
        }
        return (
          <div key={toolInvocation.toolCallId} className="space-y-2.5 mt-3">
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">
              {resultsCount} Im├│veis Encontrados
            </p>
            <div className="flex flex-col gap-2.5">
              {properties.map((prop: any) => (
                <a
                  key={prop.id}
                  href={`/imovel/${prop.id}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex gap-3 bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 p-2.5 rounded-xl shadow-sm hover:shadow-md hover:border-indigo-300 dark:hover:border-indigo-700 transition-all cursor-pointer group"
                >
                  {prop.featuredImage ? (
                    <div className="w-16 h-16 relative rounded-lg overflow-hidden shrink-0 bg-gray-100">
                      <img src={prop.featuredImage} alt={prop.title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300" />
                    </div>
                  ) : (
                    <div className="w-16 h-16 bg-indigo-50 dark:bg-white/5 rounded-lg flex items-center justify-center shrink-0">
                      <Building className="text-indigo-400" size={20} />
                    </div>
                  )}
                  <div className="flex flex-col justify-center flex-1 min-w-0">
                    <p className="font-bold text-xs truncate text-gray-900 dark:text-white">{prop.title}</p>
                    <p className="text-indigo-600 dark:text-indigo-400 font-black text-sm mt-0.5">
                      R$ {prop.price.toLocaleString('pt-BR')}
                    </p>
                    <div className="flex items-center gap-2.5 text-[10px] text-gray-400 mt-1 font-semibold">
                      <span className="flex items-center gap-1"><Bed size={10}/> {prop.bedrooms} qts</span>
                      <span className="flex items-center gap-1"><Maximize size={10}/> {prop.area}m┬▓</span>
                    </div>
                  </div>
                  <ChevronRight size={14} className="text-gray-400 self-center shrink-0 group-hover:text-indigo-500 transition-colors" />
                </a>
              ))}
            </div>
          </div>
        );
      }
    }
    return null;
  };

  // E44: Mostrar chips apenas ap├│s a ├║ltima resposta do assistente
  const lastAssistantMsg = [...messages].reverse().find(m => m.role === 'assistant');
  const showChips = lastAssistantMsg && !isLoading;

  return (
    <>
      {/* Floating Button */}
      <button
        onClick={() => setIsOpen(true)}
        className={`fixed bottom-6 right-4 sm:right-6 z-[9999] w-14 h-14 bg-gradient-to-br from-indigo-600 to-violet-600 text-white rounded-full flex items-center justify-center shadow-xl shadow-indigo-500/40 hover:scale-110 hover:shadow-indigo-500/60 transition-all duration-300 ${isOpen ? 'scale-0 opacity-0 pointer-events-none' : 'scale-100 opacity-100'}`}
      >
        <Sparkles size={22} />
        {/* E48: Ponto de notifica├º├úo proativo */}
        {showProactive && (
          <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full border-2 border-white animate-bounce" />
        )}
      </button>

      {/* Chat Window */}
